// n8n's execution API response shape is assumed based on n8n's documented
// architecture (data.data.resultData.runData keyed by node name), but this
// has not been verified against a live execution from this instance yet.
// If the real shape differs, structure_unrecognized will be true and the raw
// payload (capped) is attached instead of silently dropping data.
const exec = $json || {};
const MAX_PREVIEW = 2000;

function preview(v) {
  try {
    const s = JSON.stringify(v);
    if (!s) return null;
    return s.length > MAX_PREVIEW ? s.slice(0, MAX_PREVIEW) + '...(truncated)' : s;
  } catch (e) {
    return String(v);
  }
}

let runData = null;
try {
  runData = exec.data && exec.data.resultData && exec.data.resultData.runData;
} catch (e) {
  runData = null;
}

if (!runData || typeof runData !== 'object') {
  return [{ json: {
    available: true,
    structure_unrecognized: true,
    execution: { id: exec.id || null, workflow_id: exec.workflowId || null, status: exec.status || null, finished: exec.finished || null },
    raw: preview(exec),
  } }];
}

const nodes = [];
let agentToolCalls = [];

for (const nodeName of Object.keys(runData)) {
  const runs = runData[nodeName] || [];
  const last = runs[runs.length - 1] || {};
  const hasError = !!last.error;
  const errorInfo = hasError ? {
    name: last.error.name || null,
    message: last.error.message || null,
    description: last.error.description || null,
    stack: last.error.stack || null,
  } : null;

  const outputData = last.data && last.data.main ? last.data.main : null;

  nodes.push({
    name: nodeName,
    execution_status: last.executionStatus || (hasError ? 'error' : 'success'),
    start_time: last.startTime || null,
    execution_time_ms: last.executionTime != null ? last.executionTime : null,
    has_error: hasError,
    error: errorInfo,
    output_preview: preview(outputData),
  });

  if (/agent/i.test(nodeName) && outputData) {
    try {
      const items = outputData[0] || [];
      for (const item of items) {
        const j = item && item.json;
        if (j && Array.isArray(j.intermediateSteps)) {
          agentToolCalls = agentToolCalls.concat(j.intermediateSteps.map((s) => ({
            tool: (s.action && s.action.tool) || null,
            tool_input: preview(s.action && s.action.toolInput),
            observation: preview(s.observation),
          })));
        }
      }
    } catch (e) {
      // best-effort only - leave agentToolCalls as whatever was found so far
    }
  }
}

return [{ json: {
  available: true,
  structure_unrecognized: false,
  execution: { id: exec.id || null, workflow_id: exec.workflowId || null, status: exec.status || null, finished: exec.finished || null },
  nodes,
  agent_tool_calls: agentToolCalls,
  agent_tool_calls_note: agentToolCalls.length ? null : 'No intermediateSteps found on any node whose name matched /agent/i - either the agent made no tool calls, or n8n stores tool-call data in a different shape than assumed here.',
} }];
